const z8TICK='<svg viewBox="0 0 16 16" fill="none"><path d="M3.5 8.4 6.6 11.4 12.6 4.8" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';
function z8qr(seed){const R=z8rng(seed),n=21;let d='';const fin=(x,y)=>{d+=`M${x} ${y}h7v7h-7zM${x+1} ${y+1}v5h5v-5zM${x+2} ${y+2}h3v3h-3z`};
 for(let y=0;y<n;y++)for(let x=0;x<n;x++){const inF=(x<8&&y<8)||(x>12&&y<8)||(x<8&&y>12);if(!inF&&R()<.48)d+=`M${x} ${y}h1v1h-1z`}
 fin(0,0);fin(14,0);fin(0,14);return`<svg viewBox="-1 -1 23 23" class="z8qr"><rect x="-1" y="-1" width="23" height="23" fill="#f2f5f2"/><path d="${d}" fill="#060d0a" fill-rule="evenodd"/></svg>`}
function z8steps(){return[
 {c:T('Start shift','Anza zamu'),e:T('The rider signs in with a personal PIN on a company phone. The app will not open a wave until the battery, the locked top box and the helmet are checked, so every shift starts safe and traceable.',
  'Dereva anaingia kwa PIN yake kwenye simu ya kampuni. Programu haifungui wimbi hadi betri, sanduku la juu lililofungwa na kofia ngumu vikaguliwe, hivyo kila zamu inaanza salama na inafuatilika.')},
 {c:T('Wave 10:00','Wimbi 10:00'),e:T('At 10:00 the dispatcher releases the wave. The rider gets eight drops already in route order, each showing only the area, a short address hint, the parcel type and a time window. No names, no products, no health information.',
  'Saa 10:00 msambazaji anatoa wimbi. Dereva anapata mizigo minane tayari kwa mpangilio wa njia, kila mmoja ukionyesha eneo, dokezo fupi la anwani, aina ya mzigo na muda wa kufika. Hakuna majina, bidhaa wala taarifa za afya.')},
 {c:T('Pick and scan','Chukua na skani'),e:T('Each sealed parcel carries a QR label. The rider scans all eight at the hub; only when the count matches does the wave lock, so a wrong or missing bag is caught before the bike leaves.',
  'Kila mzigo uliofungwa una lebo ya QR. Dereva anaskani yote minane kituoni; wimbi linafungwa tu idadi ikilingana, hivyo mfuko usio sahihi au uliokosekana unagunduliwa kabla pikipiki haijaondoka.')},
 {c:T('Navigate','Elekea'),e:T('The app shows the route line and the next stop with its ETA. The customer has already received an SMS tracking link. If the rider needs directions, the call goes through a masked number.',
  'Programu inaonyesha njia na kituo kinachofuata pamoja na muda wa kufika. Mteja ameshapokea kiungo cha SMS cha kufuatilia. Dereva akihitaji maelekezo, simu inapita kwa namba iliyofichwa.')},
 {c:T('At the door','Mlangoni'),e:T('The customer reads out a 4-digit code that only they received; the rider types it in and the drop is proven. If a neighbour receives, the rider takes a photo instead. Empty Afya boxes can be collected for a TSh 1,000 credit.',
  'Mteja anataja msimbo wa tarakimu 4 aliopokea yeye peke yake; dereva anauandika na mzigo unathibitishwa. Jirani akipokea, dereva anapiga picha badala yake. Box tupu za Afya zinaweza kurudishwa kwa salio la TSh 1,000.')},
 {c:T('Delivered','Imefikishwa'),e:T('The drop is recorded with the time and the verification method, the customer gets a receipt SMS, and the next stop opens automatically.',
  'Mzigo unarekodiwa pamoja na muda na njia ya uthibitisho, mteja anapata SMS ya risiti, na kituo kinachofuata kinafunguka chenyewe.')},
 {c:T('Exceptions','Changamoto'),e:T('If the customer does not answer two calls within five minutes, the rider moves on. The parcel returns sealed to the hub and is rebooked on the next wave, and the customer is told automatically.',
  'Mteja asipojibu simu mbili ndani ya dakika tano, dereva anaendelea. Mzigo unarudi kituoni ukiwa umefungwa na unapangwa wimbi linalofuata, na mteja anaarifiwa moja kwa moja.')},
 {c:T('End of shift','Mwisho wa zamu'),e:T('The day closes with every drop accounted for, kilometres and battery swaps logged, and the day pay sent to mobile money. Every order is prepaid, so the rider never carries cash.',
  'Siku inafungwa kila mzigo ukiwa umehesabiwa, kilomita na mabadiliko ya betri yamerekodiwa, na malipo ya siku yametumwa kwa pesa ya simu. Kila oda imelipwa mapema, hivyo dereva habebi pesa taslimu.')}]}
